-- Private lead/deal attachments. Actual files and assignments stay manual.
create table portal_private.crm_lead_files(id uuid primary key,lead_id uuid not null references public.crm_leads,path text not null unique,name text not null,size bigint not null check(size between 1 and 10485760),mime text not null,actor_id uuid not null references public.profiles,reason text not null,created_at timestamptz not null default now());
create index crm_lead_file_lead on portal_private.crm_lead_files(lead_id);
create index crm_lead_file_actor on portal_private.crm_lead_files(actor_id);
create table portal_private.crm_lead_file_registers(lead_id uuid primary key references public.crm_leads,version integer not null default 0,active_files uuid[] not null default '{}' check(cardinality(active_files)<=10));
create table portal_private.crm_lead_file_history(id uuid primary key,lead_id uuid not null references public.crm_leads,file_id uuid not null references portal_private.crm_lead_files,version integer not null,action text not null check(action in ('Attached','Excluded','Restored')),payload jsonb not null,evidence jsonb not null,reason text not null,actor_id uuid not null references public.profiles,created_at timestamptz not null default now(),unique(lead_id,version));
create index crm_lead_file_history_file on portal_private.crm_lead_file_history(file_id);
create index crm_lead_file_history_actor on portal_private.crm_lead_file_history(actor_id);
do $$declare t text;begin foreach t in array array['crm_lead_files','crm_lead_file_registers','crm_lead_file_history'] loop execute format('alter table portal_private.%I enable row level security',t);execute format('revoke all on portal_private.%I from public,anon,authenticated,service_role',t);end loop;end$$;
create trigger crm_lead_file_immutable before update or delete on portal_private.crm_lead_files for each row execute function portal_private.lead_api_evidence_immutable();
create trigger crm_lead_file_history_immutable before update or delete on portal_private.crm_lead_file_history for each row execute function portal_private.lead_api_evidence_immutable();
create function portal_private.lead_file_read(p_lead uuid) returns boolean language sql stable security definer set search_path='' as $$select public.is_staff() and (portal_private.lead_access(p_lead) or exists(select 1 from public.crm_deals d where d.lead_id=p_lead and portal_private.deal_access(d.id)));$$;
create function portal_private.lead_file_edit(p_lead uuid) returns boolean language sql stable security definer set search_path='' as $$select portal_private.lead_file_read(p_lead) and portal_private.sales_user() and exists(select 1 from public.crm_leads l where l.id=p_lead and (l.status<>'Assigned' and (public.is_admin() or portal_private.crm_permission('sales.manage') or l.owner_id=auth.uid()) or exists(select 1 from public.crm_deals d where d.lead_id=l.id and d.stage not in ('won','lost') and portal_private.deal_edit(d.id))));$$;
create function portal_private.lead_file_upload(p_path text) returns boolean language sql stable security definer set search_path='' as $$select p_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(pdf|png|jpg|jpeg|webp)$' and exists(select 1 from public.crm_leads l where l.id::text=split_part(p_path,'/',1) and portal_private.lead_file_edit(l.id) and coalesce((select cardinality(active_files) from portal_private.crm_lead_file_registers where lead_id=l.id),0)<10 and (select count(*) from portal_private.crm_lead_files where lead_id=l.id)<20);$$;
create function portal_private.lead_file_object_read(p_path text,p_owner text) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.crm_leads l where l.id::text=split_part(p_path,'/',1) and portal_private.lead_file_read(l.id)) and (exists(select 1 from portal_private.crm_lead_files f where f.path=p_path) or p_owner=auth.uid()::text);$$;
create function portal_private.lead_file_orphan(p_path text) returns boolean language plpgsql security definer set search_path='' as $$begin perform pg_advisory_xact_lock(hashtextextended('crm-lead-file:'||p_path,0));return not exists(select 1 from portal_private.crm_lead_files where path=p_path);end$$;
revoke all on function portal_private.lead_file_read(uuid),portal_private.lead_file_edit(uuid),portal_private.lead_file_upload(text),portal_private.lead_file_object_read(text,text),portal_private.lead_file_orphan(text) from public,anon,authenticated,service_role;
grant execute on function portal_private.lead_file_upload(text),portal_private.lead_file_object_read(text,text),portal_private.lead_file_orphan(text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('crm-lead-files','crm-lead-files',false,10485760,array['application/pdf','image/png','image/jpeg','image/webp']);
create policy crm_lead_files_upload on storage.objects for insert to authenticated with check(bucket_id='crm-lead-files' and owner_id=auth.uid()::text and portal_private.lead_file_upload(name));
create policy crm_lead_files_read on storage.objects for select to authenticated using(bucket_id='crm-lead-files' and portal_private.lead_file_object_read(name,owner_id));
create policy crm_lead_files_cleanup on storage.objects for delete to authenticated using(bucket_id='crm-lead-files' and owner_id=auth.uid()::text and portal_private.lead_file_orphan(name));
create policy crm_lead_files_read_boundary on storage.objects as restrictive for select to authenticated using(bucket_id<>'crm-lead-files' or portal_private.lead_file_object_read(name,owner_id));
create policy crm_lead_files_upload_boundary on storage.objects as restrictive for insert to authenticated with check(bucket_id<>'crm-lead-files' or owner_id=auth.uid()::text and portal_private.lead_file_upload(name));
create policy crm_lead_files_cleanup_boundary on storage.objects as restrictive for delete to authenticated using(bucket_id<>'crm-lead-files' or owner_id=auth.uid()::text and portal_private.lead_file_orphan(name));
create policy crm_lead_files_no_overwrite on storage.objects as restrictive for update to authenticated using(bucket_id<>'crm-lead-files') with check(bucket_id<>'crm-lead-files');
create policy crm_lead_files_no_anon on storage.objects as restrictive for all to anon using(bucket_id<>'crm-lead-files') with check(bucket_id<>'crm-lead-files');
create function portal_private.protect_lead_file_object() returns trigger language plpgsql security definer set search_path='' as $$begin
 if old.bucket_id='crm-lead-files' then perform pg_advisory_xact_lock(hashtextextended('crm-lead-file:'||old.name,0));if exists(select 1 from portal_private.crm_lead_files where path=old.name) then raise exception 'Registered lead file bytes and path are retained';end if;end if;
 if tg_op='DELETE' then return old;end if;return new;
end$$;
revoke all on function portal_private.protect_lead_file_object() from public,anon,authenticated,service_role;
create trigger crm_lead_file_object_retention before update or delete on storage.objects for each row execute function portal_private.protect_lead_file_object();
create function public.crm_lead_file_context(p_lead uuid,p_before integer default null) returns jsonb language plpgsql stable security definer set search_path='' as $$declare r portal_private.crm_lead_file_registers;files jsonb;history jsonb;begin
 if not portal_private.lead_file_read(p_lead) then raise exception 'Current actual lead access required';end if;
 select * into r from portal_private.crm_lead_file_registers where lead_id=p_lead;
 select coalesce(jsonb_agg(to_jsonb(f)||jsonb_build_object('active',f.id=any(coalesce(r.active_files,'{}')),'stored_metadata_matches',o.id is not null and o.owner_id=f.actor_id::text and o.metadata->>'size'=f.size::text and o.metadata->>'mimetype'=f.mime) order by f.created_at,f.id),'[]') into files from portal_private.crm_lead_files f left join storage.objects o on o.bucket_id='crm-lead-files' and o.name=f.path where f.lead_id=p_lead;
 select coalesce(jsonb_agg(to_jsonb(h) order by h.version desc),'[]') into history from (select * from portal_private.crm_lead_file_history where lead_id=p_lead and (p_before is null or version<p_before) order by version desc limit 100) h;
 return jsonb_build_object('lead_id',p_lead,'version',coalesce(r.version,0),'status',case when portal_private.lead_file_edit(p_lead) then 'Editable' else 'Read-only' end,'can_edit',portal_private.lead_file_edit(p_lead),'files',files,'history',history,'has_more',exists(select 1 from portal_private.crm_lead_file_history where lead_id=p_lead and version<(select min((x->>'version')::integer) from jsonb_array_elements(history) x)));
end$$;
create function public.attach_crm_lead_file(p_id uuid,p_lead uuid,p_version integer,p_path text,p_name text,p_reason text) returns uuid language plpgsql security definer set search_path='' as $$declare r portal_private.crm_lead_file_registers;old portal_private.crm_lead_file_history;o storage.objects;f portal_private.crm_lead_files;payload jsonb;ext text;mime text;scope_deal uuid;begin
 if not portal_private.lead_file_read(p_lead) then raise exception 'Current actual lead access required';end if;
 if p_id is null or p_name is null or length(trim(p_name)) not between 1 and 160 or p_name ~ '[[:cntrl:]/\\]' or length(trim(coalesce(p_reason,''))) not between 3 and 2000 then raise exception 'Safe actual filename, identity and reason required';end if;
 ext:=lower(substring(p_path from '\.([^.]+)$'));mime:=case ext when 'pdf' then 'application/pdf' when 'png' then 'image/png' when 'jpg' then 'image/jpeg' when 'jpeg' then 'image/jpeg' when 'webp' then 'image/webp' end;
 if mime is null or p_path is distinct from p_lead::text||'/'||p_id::text||'.'||ext or lower(substring(p_name from '\.([^.]+)$')) is distinct from ext then raise exception 'Actual lead/file path and matching PDF/image filename required';end if;
 payload:=jsonb_build_object('lead',p_lead,'version',p_version,'path',p_path,'name',p_name,'reason',p_reason);
 perform pg_advisory_xact_lock(hashtextextended('crm-lead-file:'||p_path,0));
 select * into old from portal_private.crm_lead_file_history where id=p_id;
 if found then if old.actor_id<>auth.uid() or old.action<>'Attached' or old.payload<>payload then raise exception 'Request reused with different actual meaning';end if;return old.file_id;end if;
 perform 1 from public.profiles where id=auth.uid() and active for share;select id into scope_deal from public.crm_deals where lead_id=p_lead for share;perform 1 from public.crm_leads where id=p_lead for update;
 if (select id from public.crm_deals where lead_id=p_lead) is distinct from scope_deal then raise exception 'Lead was assigned concurrently. Refresh first';end if;
 perform 1 from public.crm_board_memberships where user_id=auth.uid() order by board_id for share;
 perform 1 from public.crm_memberships where user_id=auth.uid() order by role_id,team_id for share;
 perform 1 from public.crm_roles order by id for share;
 perform 1 from public.crm_teams where id in(select team_id from public.crm_memberships where user_id=auth.uid()) order by id for share;
 if not portal_private.lead_file_edit(p_lead) then raise exception 'Current editable lead authority required';end if;
 insert into portal_private.crm_lead_file_registers(lead_id) values(p_lead) on conflict do nothing;select * into r from portal_private.crm_lead_file_registers where lead_id=p_lead for update;
 if r.version is distinct from p_version or cardinality(r.active_files)>=10 or (select count(*) from portal_private.crm_lead_files where lead_id=p_lead)>=20 then raise exception 'File register changed or technical file limit reached. Refresh first';end if;
 select * into o from storage.objects where bucket_id='crm-lead-files' and name=p_path and owner_id=auth.uid()::text for share;
 if not found or o.metadata->>'mimetype' is distinct from mime or coalesce(o.metadata->>'size','')!~'^[0-9]{1,8}$' or (o.metadata->>'size')::bigint not between 1 and 10485760 then raise exception 'Actual uploaded file metadata missing or mismatched';end if;
 insert into portal_private.crm_lead_files values(p_id,p_lead,p_path,trim(p_name),(o.metadata->>'size')::bigint,mime,auth.uid(),trim(p_reason),now()) returning * into f;
 update portal_private.crm_lead_file_registers set active_files=array_append(active_files,p_id),version=version+1 where lead_id=p_lead;
 insert into portal_private.crm_lead_file_history values(p_id,p_lead,p_id,r.version+1,'Attached',payload,to_jsonb(f),trim(p_reason),auth.uid(),now());return p_id;
end$$;
create function public.change_crm_lead_file(p_id uuid,p_file uuid,p_version integer,p_action text,p_reason text) returns void language plpgsql security definer set search_path='' as $$declare f portal_private.crm_lead_files;r portal_private.crm_lead_file_registers;old portal_private.crm_lead_file_history;payload jsonb;scope_deal uuid;begin
 select * into f from portal_private.crm_lead_files where id=p_file;
 if not found or not portal_private.lead_file_read(f.lead_id) then raise exception 'Current actual lead file access required';end if;
 if p_id is null or p_action is null or p_action not in ('Excluded','Restored') or length(trim(coalesce(p_reason,''))) not between 3 and 2000 then raise exception 'Explicit file action and reason required';end if;
 payload:=jsonb_build_object('file',p_file,'version',p_version,'action',p_action,'reason',p_reason);
 perform pg_advisory_xact_lock(hashtextextended('crm-lead-file:'||f.path,0));
 select * into old from portal_private.crm_lead_file_history where id=p_id;
 if found then if old.actor_id<>auth.uid() or old.payload<>payload then raise exception 'Request reused with different actual meaning';end if;return;end if;
 perform 1 from public.profiles where id=auth.uid() and active for share;select id into scope_deal from public.crm_deals where lead_id=f.lead_id for share;perform 1 from public.crm_leads where id=f.lead_id for update;
 if (select id from public.crm_deals where lead_id=f.lead_id) is distinct from scope_deal then raise exception 'Lead was assigned concurrently. Refresh first';end if;
 select * into r from portal_private.crm_lead_file_registers where lead_id=f.lead_id for update;
 perform 1 from public.crm_board_memberships where user_id=auth.uid() order by board_id for share;
 perform 1 from public.crm_memberships where user_id=auth.uid() order by role_id,team_id for share;
 perform 1 from public.crm_roles order by id for share;
 perform 1 from public.crm_teams where id in(select team_id from public.crm_memberships where user_id=auth.uid()) order by id for share;
 if not portal_private.lead_file_edit(f.lead_id) or r.version is distinct from p_version then raise exception 'Current editable lead and exact file register required';end if;
 if p_action='Excluded' and not(p_file=any(r.active_files)) or p_action='Restored' and (p_file=any(r.active_files) or cardinality(r.active_files)>=10) then raise exception 'File status changed or active limit reached';end if;
 if p_action='Restored' then perform 1 from storage.objects where bucket_id='crm-lead-files' and name=f.path and owner_id=f.actor_id::text and metadata->>'size'=f.size::text and metadata->>'mimetype'=f.mime for share;if not found then raise exception 'Actual stored file metadata changed';end if;end if;
 update portal_private.crm_lead_file_registers set active_files=case when p_action='Excluded' then array_remove(active_files,p_file) else array_append(active_files,p_file) end,version=version+1 where lead_id=f.lead_id;
 insert into portal_private.crm_lead_file_history values(p_id,f.lead_id,p_file,r.version+1,p_action,payload,jsonb_build_object('file',to_jsonb(f),'before_active',r.active_files,'after_active',case when p_action='Excluded' then array_remove(r.active_files,p_file) else array_append(r.active_files,p_file) end),trim(p_reason),auth.uid(),now());
end$$;
revoke all on function public.crm_lead_file_context(uuid,integer),public.attach_crm_lead_file(uuid,uuid,integer,text,text,text),public.change_crm_lead_file(uuid,uuid,integer,text,text) from public,anon,service_role;
grant execute on function public.crm_lead_file_context(uuid,integer),public.attach_crm_lead_file(uuid,uuid,integer,text,text,text),public.change_crm_lead_file(uuid,uuid,integer,text,text) to authenticated;
